19	// Fingerprinted asset produced by blog-src/scripts/fingerprint-assets.mjs,
20	// e.g. /css/style.4c1f0b9a2e.css. Captures the unhashed path so a hash from
21	// a previous deploy (referenced by CDN-cached HTML) can fall back to the
22	// current copy instead of 404ing.
23	const HASHED_ASSET = /^(\/(?:css|js)\/.+)\.[0-9a-f]{10}(\.(?:css|js))$/;
24	
25	// Astro/Vite bundle asset, e.g. /_astro2/BlogLayout.CBvvIjZz.css (directory
26	// name set by build.assets in blog-src/astro.config.mjs). There is no
27	// unhashed original for these, so a stale hash is resolved through
28	// /_astro-manifest.json (written by blog-src/scripts/astro-manifest.mjs),
29	// which maps the stable base name to the current build's file. The legacy
30	// /_astro prefix is still matched so HTML cached before the directory was
31	// renamed keeps resolving its stylesheets through the manifest.
32	const ASTRO_ASSET = /^\/_astro2?\/(.+)\.[A-Za-z0-9_-]{8}(\.(?:css|js))$/;
33	
34	// The assets layer attaches _headers path rules (max-age=31536000, immutable
35	// for /css, /js, /_astro) to 404 responses too. A 404 cached as immutable
36	// poisons that URL in the browser for a year — and fingerprinted URLs never
37	// change while the file's content is unchanged, so the client never recovers
38	// on its own. No 404 may leave this worker with a cacheable lifetime.
39	function uncacheable(response: Response): Response {
40	  const headers = new Headers(response.headers);
41	  headers.set('Cache-Control', 'no-store');
42	  headers.delete('CDN-Cache-Control');
43	  return new Response(response.body, { status: response.status, statusText: response.statusText, headers });
44	}
