46	// Fallback responses bridge stale cached HTML to the current build, but they
47	// are served under the *stale* URL — they must not inherit the current
48	// asset's immutable header, or the bridge content gets pinned for a year.
49	function bridged(response: Response): Response {
50	  if (!response.ok) return uncacheable(response);
51	  const headers = new Headers(response.headers);
52	  headers.set('Cache-Control', 'public, max-age=300, must-revalidate');
53	  headers.set('CDN-Cache-Control', 'public, max-age=300, must-revalidate');
54	  return new Response(response.body, { status: response.status, statusText: response.statusText, headers });
55	}
