4	const THANK_YOU = '/thank-you/';
5	// Email delivery failed but the submission is safely stored — tell the sender
6	// it was received rather than bouncing them to the error page (which invites
7	// a duplicate resubmission).
8	const THANK_YOU_DELAYED = '/thank-you/?delivery=delayed';
9	const CONTACT_ERROR = '/contact-error/';
10	// Rate limit: at most this many attempts from one IP within the window.
11	// Counted against contact_attempts — every POST that reaches the Turnstile
12	// check — so failing the challenge repeatedly can't be used to hammer
13	// siteverify and D1 for free.
14	const RATE_LIMIT_MAX = 5;
15	const RATE_LIMIT_WINDOW_MS = 60 * 60 * 1000; // 1 hour
16	// Submissions older than this are purged opportunistically on each accepted request.
17	const RETENTION_MS = 90 * 86_400_000;
18	const MAX_NAME_LEN = 200;
19	const MAX_EMAIL_LEN = 200;
20	const MAX_MESSAGE_LEN = 5000;
21	const MAX_FORM_BYTES = 32 * 1024;
22	// Cap time spent waiting on Turnstile / ForwardEmail so a hung upstream
23	// can't stall the request until the platform kills it.
24	const UPSTREAM_TIMEOUT_MS = 10_000;
25	
26	// Strip CR/LF and other control characters that could be used to inject
27	// extra email headers downstream when name/email are interpolated into
28	// replyTo / subject / body.
29	// eslint-disable-next-line no-control-regex -- matching control chars is the point
30	const stripControl = (s: string) => s.replace(/[\x00-\x1f\x7f]/g, '');
31	
32	// Stricter email validation than \S+@\S+\.\S+ — requires a 2+ char TLD,
33	// rejects whitespace, multiple @, leading/trailing dots, etc.
34	const EMAIL_RE = /^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,63}$/;
35	
36	// Display-name for the notification's Reply-To, quoted per RFC 5322 with `"`
37	// and `\` stripped. Without quoting, a crafted name like `x <a@evil.com>,`
38	// could smuggle a second address into the address list ForwardEmail parses.
39	const quoteDisplayName = (s: string) => `"${s.replace(/[\\"]/g, '')}"`;
