54	// Read the request body with a hard byte cap. The Content-Length header is
55	// client-controlled and absent on chunked uploads, so the cap has to be
56	// enforced on the actual stream. Returns null when the cap is exceeded.
57	async function readBodyCapped(request: Request, maxBytes: number): Promise<Uint8Array | null> {
58	  if (!request.body) return new Uint8Array(0);
59	  const reader = request.body.getReader();
60	  const chunks: Uint8Array[] = [];
61	  let total = 0;
62	  for (let read = await reader.read(); !read.done; read = await reader.read()) {
63	    total += read.value.byteLength;
64	    if (total > maxBytes) {
65	      await reader.cancel();
66	      return null;
67	    }
68	    chunks.push(read.value);
69	  }
70	  const buf = new Uint8Array(total);
71	  let offset = 0;
72	  for (const chunk of chunks) {
73	    buf.set(chunk, offset);
74	    offset += chunk.byteLength;
75	  }
76	  return buf;
77	}
