106	export async function handleContact(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
107	  const url = new URL(request.url);
108	  const redirectTo = (path: string) =>
109	    new Response(null, { status: 303, headers: { Location: url.origin + path, ...NO_STORE } });
110	  // Log-and-bounce helper: every rejection path emits one structured warning
111	  // and lands the user on the friendly error page.
112	  const reject = (reason: string, details?: Record<string, unknown>) => {
113	    console.warn(`contact: rejected on ${reason}`, details ?? {});
114	    return redirectTo(CONTACT_ERROR);
115	  };
116	
117	  // Same-origin enforcement: every modern browser sends `Origin` on POST.
118	  // A legitimate form submission from this site matches `url.origin`.
119	  // Reject anything else — including requests with NO Origin — to close the
120	  // cross-site form bypass that the prior `if (origin && ...)` left open.
121	  const origin = request.headers.get('Origin');
122	  if (origin !== url.origin) {
123	    console.warn('contact: rejected on origin mismatch', { origin, expected: url.origin });
124	    return plain(403, 'Forbidden');
125	  }
126	
127	  const contentType = request.headers.get('Content-Type') ?? '';
128	  if (
129	    !contentType.startsWith('application/x-www-form-urlencoded') &&
130	    !contentType.startsWith('multipart/form-data')
131	  ) {
132	    return plain(415, 'Unsupported media type');
133	  }
134	
135	  // Fast reject on the declared size, then enforce the same cap on the real
136	  // stream — Content-Length is client-controlled and absent on chunked bodies.
137	  const contentLength = Number(request.headers.get('Content-Length') ?? '0');
138	  if (contentLength > MAX_FORM_BYTES) {
139	    console.warn('contact: rejected on body size', { contentLength, max: MAX_FORM_BYTES });
140	    return plain(413, 'Payload too large');
141	  }
142	  const rawBody = await readBodyCapped(request, MAX_FORM_BYTES);
143	  if (rawBody === null) {
144	    console.warn('contact: rejected on body size (stream cap)', { max: MAX_FORM_BYTES });
145	    return plain(413, 'Payload too large');
146	  }
147	
148	  let form: FormData;
149	  try {
150	    form = await new Response(rawBody, { headers: { 'Content-Type': contentType } }).formData();
151	  } catch {
152	    return plain(400, 'Bad request');
153	  }
154	
155	  if (form.get('bot-field')) return redirectTo(THANK_YOU);
156	
157	  const name = stripControl(String(form.get('name') ?? '').trim()).slice(0, MAX_NAME_LEN);
158	  const email = stripControl(String(form.get('email') ?? '').trim()).slice(0, MAX_EMAIL_LEN);
159	  const message = String(form.get('message') ?? '').trim().slice(0, MAX_MESSAGE_LEN);
160	  const token = String(form.get('cf-turnstile-response') ?? '');
161	
162	  if (!name || !message || !EMAIL_RE.test(email)) {
163	    return reject('validation', { hasName: !!name, hasMessage: !!message, emailOk: EMAIL_RE.test(email) });
164	  }
165	
166	  if (!token) {
167	    return reject('missing turnstile token');
168	  }
169	
170	  const ip = request.headers.get('CF-Connecting-IP') ?? '';
171	
172	  if (ip) {
173	    const now = Date.now();
174	    const since = now - RATE_LIMIT_WINDOW_MS;
175	    // Count *attempts*, not accepted submissions — otherwise a client that
176	    // keeps failing Turnstile gets unlimited free runs at siteverify.
177	    const recent = await env.DB.prepare(
178	      'SELECT COUNT(*) AS n FROM contact_attempts WHERE ip = ?1 AND ts > ?2'
179	    ).bind(ip, since).first<{ n: number }>();
180	    if (recent && recent.n >= RATE_LIMIT_MAX) {
181	      return reject('rate limit', { ip, recent: recent.n });
182	    }
183	    await env.DB.prepare(
184	      'INSERT INTO contact_attempts (ip, ts) VALUES (?1, ?2)'
185	    ).bind(ip, now).run();
186	    // Attempts only matter within the rate-limit window; prune the old ones
187	    // on every recorded attempt so the table can't grow unbounded even if no
188	    // submission is ever accepted.
189	    ctx.waitUntil(
190	      env.DB.prepare('DELETE FROM contact_attempts WHERE ts < ?1').bind(since).run()
191	        .catch(err => console.error('attempt purge failed:', err))
192	    );
193	  }
194	
195	  const tsBody = new FormData();
196	  tsBody.set('secret', env.TURNSTILE_SECRET);
197	  tsBody.set('response', token);
198	  if (ip) tsBody.set('remoteip', ip);
199	
200	  // Fail closed: a siteverify outage, timeout, or malformed response means we
201	  // could not verify the human — bounce to the error page instead of letting
202	  // the exception surface as an opaque 500 (or worse, skipping verification).
203	  let tsJson: { success: boolean; 'error-codes'?: string[] };
204	  try {
205	    const tsRes = await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify', {
206	      method: 'POST',
207	      body: tsBody,
208	      signal: AbortSignal.timeout(UPSTREAM_TIMEOUT_MS),
209	    });
210	    tsJson = (await tsRes.json()) as { success: boolean; 'error-codes'?: string[] };
211	  } catch (err) {
212	    return reject('turnstile verify error', { error: String(err) });
213	  }
214	  if (!tsJson.success) {
215	    return reject('turnstile', { errors: tsJson['error-codes'] });
216	  }
217	
218	  await env.DB.prepare(
219	    'INSERT INTO submissions (name, email, message, ip, ts) VALUES (?1, ?2, ?3, ?4, ?5)'
220	  ).bind(name, email, message, ip, Date.now()).run();
221	
222	  // Opportunistic retention purge — kept off the response path via waitUntil.
223	  // Cloudflare's free Workers plan caps cron triggers per account, so we
224	  // piggy-back on accepted submissions instead of using a scheduled handler.
225	  const retentionCutoff = Date.now() - RETENTION_MS;
226	  ctx.waitUntil(
227	    env.DB.prepare('DELETE FROM submissions WHERE ts < ?1').bind(retentionCutoff).run()
228	      .catch(err => console.error('retention purge failed:', err))
229	  );
230	
231	  // Fire the branded thank-you auto-reply to the sender as a best-effort side
232	  // task. It rides on ctx.waitUntil so a slow or failing send never delays the
233	  // user's redirect or downgrades their acknowledgement — the auto-reply is a
234	  // courtesy, not part of the delivery guarantee. replyTo points back at the
235	  // owner so a reply from the sender still lands in the right inbox. Gated
236	  // behind Turnstile + the per-IP rate limit above, which bounds any use of
237	  // this as a reflector toward a spoofed address.
238	  const autoReply = renderAutoReplyEmail({ name });
239	  ctx.waitUntil(
240	    sendMail(env, {
241	      from: env.CONTACT_FROM,
242	      to: email,
243	      replyTo: env.CONTACT_TO,
244	      subject: autoReply.subject,
245	      html: autoReply.html,
246	      text: autoReply.text,
247	    })
248	      .then(res => {
249	        if (!res.ok) console.error('auto-reply failed', res.status);
250	        else console.log('auto-reply sent ok', res.status);
251	      })
252	      .catch(err => console.error('auto-reply fetch failed:', String(err))),
253	  );
254	
255	  // The owner notification is the delivery that matters — its failure is what
256	  // decides whether the sender sees the delayed-delivery acknowledgement.
257	  const notification = renderNotificationEmail({ name, email, message, ip });
258	  let mailRes: Response;
259	  try {
260	    mailRes = await sendMail(env, {
261	      from: env.CONTACT_FROM,
262	      to: env.CONTACT_TO,
263	      replyTo: `${quoteDisplayName(name)} <${email}>`,
264	      subject: notification.subject,
265	      html: notification.html,
266	      text: notification.text,
267	    });
268	  } catch (err) {
269	    // The submission is safely recorded in D1 — acknowledge receipt instead
270	    // of showing an error that would prompt a duplicate resubmission.
271	    console.error('ForwardEmail fetch failed:', String(err));
272	    return redirectTo(THANK_YOU_DELAYED);
273	  }
274	
275	  if (!mailRes.ok) {
276	    const errBody = await mailRes.text();
277	    const requestId = mailRes.headers.get('X-Request-Id') ?? '';
278	    console.error('ForwardEmail failed', mailRes.status, 'request-id=', requestId, 'err=', errBody);
279	    // The submission is safely recorded in D1 — acknowledge receipt.
280	    return redirectTo(THANK_YOU_DELAYED);
281	  }
282	  console.log('ForwardEmail sent ok', mailRes.status);
283	
284	  return redirectTo(THANK_YOU);
285	}

